const i = $input.first().json || {};
const vac = Number(i.vacancy_id) || 0;
const cand = Number(i.candidate_id) || 0;
return [{ json: {
  vacancy_id: vac,
  candidate_id: cand,
  criteria_sql: "SELECT criteria FROM recruiter_compass.vacancy_criteria_versions WHERE potok_vacancy_id = " + vac + " AND status = 'confirmed' ORDER BY version_number DESC LIMIT 1",
  review_sql: "SELECT potok_candidate_id, recommendation, summary, evidence, critical_unknowns FROM recruiter_compass.candidate_reviews WHERE potok_vacancy_id = " + vac + " AND potok_candidate_id = " + cand + " ORDER BY created_at DESC LIMIT 1"
} }];

const crit = $('Критерии').first().json.criteria || [];
const titleMap = {};
crit.forEach(function(c) { if (c && c.criterion_id) { titleMap[c.criterion_id] = c.title; } });
const ids = Object.keys(titleMap).sort(function(a, b) { return b.length - a.length; });
const clean = function(t) { if (t === undefined || t === null) { return t; } var s = String(t); ids.forEach(function(k) { s = s.split(k).join(titleMap[k]); }); return s; };
const stateLabel = { confirmed: 'подтверждено', partially_confirmed: 'частично', needs_clarification: 'уточнить', not_met: 'не соответствует' };
const recLabel = { continue: 'вести дальше', clarify: 'уточнить', not_for_current_vacancy: 'не подходит', consider_neighbour_role: 'соседняя роль' };
const revItems = $('Разбор').all();
const rev = (revItems && revItems[0] && revItems[0].json && revItems[0].json.potok_candidate_id) ? revItems[0].json : null;
if (!rev) { return [{ json: { ok: true, data: { candidate_id: null, recommendation: 'нет данных', summary: 'Разбор кандидата ещё не сохранён. Запросите разбор кандидатов по вакансии.', evidence: [], critical_unknowns: [] } } }]; }
const evidence = (rev.evidence || []).map(function(e) { return { title: titleMap[e.criterion_id] || e.criterion_id, state: stateLabel[e.state] || e.state, claim: clean(e.claim) }; });
const unknowns = (rev.critical_unknowns || []).map(function(u) { return { title: titleMap[u.criterion_id] || u.criterion_id, question: clean(u.question) }; });
return [{ json: { ok: true, data: { candidate_id: rev.potok_candidate_id, recommendation: recLabel[rev.recommendation] || rev.recommendation, summary: clean(rev.summary || ''), evidence: evidence, critical_unknowns: unknowns } } }];

